DECLARE payload jsonb:='{"before":[{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"87e16c9815c1c210990b37eb3fb645d0","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"3b48db03f9bacaddcbd28ff69514f10a","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.read_preview_version_group(p_creation_id uuid, p_owner_type text, p_owner_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"39a3793db4897cd65bfbbc17da1a0471","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true}],"patches":[{"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","before":{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"87e16c9815c1c210990b37eb3fb645d0","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_asset public.user_assets%rowtype;\n  v_cleanup_id uuid;\nbegin\n  if p_owner_type not in (''anon'', ''customer'') then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''anon'' and (p_anon_session_id is null or p_customer_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''customer'' and (p_customer_id is null or p_anon_session_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n\n  select asset.*\n  into v_asset\n  from public.user_assets asset\n  where asset.asset_id = p_asset_id\n  for update;\n\n  if not found then\n    raise exception ''user_asset_not_found'' using errcode = ''P0002'';\n  end if;\n\n  if v_asset.owner_type::text <> p_owner_type\n    or v_asset.anon_session_id is distinct from p_anon_session_id\n    or v_asset.customer_id is distinct from p_customer_id then\n    raise exception ''user_asset_owner_mismatch'' using errcode = ''42501'';\n  end if;\n\n  IF v_asset.asset_type::text=''face_image'' THEN\n    IF public.customer_media_referenced(public.customer_media_path(v_asset.storage_path),p_asset_id) THEN\n      RAISE EXCEPTION ''face_asset_bound'' USING ERRCODE=''23503''; END IF;\n    v_cleanup_id:=public.enqueue_unused_customer_face(p_asset_id);\n    RETURN QUERY SELECT v_cleanup_id,''raw-private''::text,v_asset.storage_path;\n    RETURN;\n  END IF;\n  if exists (\n    select 1\n    from public.creations creation\n    where creation.voice_asset_id = p_asset_id\n    UNION ALL SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.asset_id=p_asset_id\n    UNION ALL SELECT 1 FROM public.order_line_voice line WHERE line.voice_asset_id=p_asset_id\n  ) then\n    raise exception ''voice_asset_bound'' using errcode = ''23503'';\n  end if;\n\n  if nullif(btrim(v_asset.storage_path), '''') is not null then\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      next_attempt_at,\n      updated_at\n    )\n    values (\n      v_asset.asset_id,\n      v_asset.asset_type::text,\n      ''raw-private'',\n      v_asset.storage_path,\n      ''owner_delete'',\n      ''pending'',\n      now(),\n      now()\n    )\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        next_attempt_at = now(),\n        updated_at = now()\n    returning public.user_asset_cleanup_outbox.cleanup_id into v_cleanup_id;\n  end if;\n\n  delete from public.user_assets asset\n  where asset.asset_id = v_asset.asset_id;\n\n  return query\n  select v_cleanup_id, ''raw-private''::text, v_asset.storage_path;\nend;\n","after_md5":"5b5db790ec5db14d788dbc7aff666e6b"},{"identity":"public.claim_user_asset_cleanup(p_limit integer)","before":{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"3b48db03f9bacaddcbd28ff69514f10a","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\nDECLARE q public.user_asset_cleanup_outbox%rowtype; token uuid;\nBEGIN\n  IF p_limit NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION ''voice_cleanup_input_invalid'' USING ERRCODE=''22023''; END IF;\n  FOR q IN SELECT cleanup.* FROM public.user_asset_cleanup_outbox cleanup\n    WHERE ((cleanup.cleanup_status=''pending'' AND cleanup.next_attempt_at<=now())\n      OR (cleanup.cleanup_status=''processing'' AND cleanup.claimed_at<now()-interval ''15 minutes''))\n      AND NOT EXISTS(SELECT 1 FROM public.order_line_voice v JOIN public.user_assets a ON a.asset_id=v.voice_asset_id\n        WHERE cleanup.bucket_name=''raw-private'' AND a.storage_path=cleanup.storage_path)\n      AND NOT EXISTS(SELECT 1 FROM public.creations c JOIN public.user_assets a ON a.asset_id=c.voice_asset_id\n        WHERE cleanup.bucket_name=''raw-private'' AND a.storage_path=cleanup.storage_path)\n      AND NOT EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.bucket_name=cleanup.bucket_name\n        AND p.storage_path=cleanup.storage_path AND p.retained_after_shipment)\n      AND (cleanup.asset_type NOT IN (''face_image'',''preview_output'')\n        OR NOT public.customer_media_referenced(cleanup.storage_path,cleanup.asset_id))\n    ORDER BY cleanup.created_at,cleanup.cleanup_id FOR UPDATE SKIP LOCKED LIMIT p_limit\n  LOOP\n    -- Match the binder''s asset lock; the following statement sees committed references after waiting.\n    PERFORM 1 FROM public.user_assets a WHERE q.bucket_name=''raw-private''\n      AND (a.asset_id=q.asset_id OR a.storage_path=q.storage_path) ORDER BY a.asset_id FOR UPDATE;\n    IF q.bucket_name=''raw-private'' AND EXISTS(SELECT 1 FROM public.user_assets a\n      WHERE a.storage_path=q.storage_path AND\n        (EXISTS(SELECT 1 FROM public.order_line_voice v WHERE v.voice_asset_id=a.asset_id)\n          OR EXISTS(SELECT 1 FROM public.creations c WHERE c.voice_asset_id=a.asset_id))) THEN\n      UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,\n        next_attempt_at=greatest(next_attempt_at,clock_timestamp()+interval ''1 hour''),updated_at=clock_timestamp()\n        WHERE cleanup_id=q.cleanup_id;\n      CONTINUE;\n    END IF;\n    -- Fresh checks AFTER asset lock wait; do not use audit JSON as provenance.\n    IF EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.bucket_name=q.bucket_name\n      AND p.storage_path=q.storage_path AND p.retained_after_shipment) THEN\n      UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,\n        next_attempt_at=greatest(next_attempt_at,clock_timestamp()+interval ''1 hour''),updated_at=clock_timestamp()\n        WHERE cleanup_id=q.cleanup_id;\n      CONTINUE;\n    END IF;\n    IF EXISTS(SELECT 1 FROM public.support_questions s WHERE s.closed_at IS NULL\n      AND (s.order_id=q.order_id OR s.order_id IN (SELECT p.order_id FROM public.user_asset_cleanup_provenance p\n        WHERE p.bucket_name=q.bucket_name AND p.storage_path=q.storage_path))) THEN\n      UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,\n        next_attempt_at=greatest(next_attempt_at,clock_timestamp()+interval ''1 hour''),updated_at=clock_timestamp()\n        WHERE cleanup_id=q.cleanup_id;\n      CONTINUE;\n    END IF;\n    -- Removing locked unbound metadata prevents rebind during external deletion.\n    IF q.asset_type=''voice_sample'' AND EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p\n      WHERE p.bucket_name=q.bucket_name AND p.storage_path=q.storage_path) THEN\n      DELETE FROM public.user_assets WHERE asset_id=q.asset_id AND storage_path=q.storage_path;\n    END IF;\n    IF q.asset_type IN (''face_image'',''preview_output'')\n      AND public.customer_media_referenced(q.storage_path,q.asset_id) THEN\n      UPDATE public.user_asset_cleanup_outbox SET next_attempt_at=greatest(next_attempt_at,clock_timestamp()+interval ''1 hour''),\n        cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,updated_at=clock_timestamp() WHERE cleanup_id=q.cleanup_id;\n      CONTINUE;\n    END IF;\n    token:=gen_random_uuid();\n    UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''processing'',processing_token=token,\n      claimed_at=now(),updated_at=now() WHERE cleanup_id=q.cleanup_id;\n    RETURN QUERY SELECT q.cleanup_id,q.bucket_name,q.storage_path,token;\n  END LOOP;\nEND\n","after_md5":"9ecfe7627c3b3b50fff2c215f3bc0831"}],"core":"-- Offline S1 core; installed atomically by the generated exact-fenced migration.\nCREATE FUNCTION public.customer_media_path(p text) RETURNS text\nLANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path='''' AS $$\n SELECT regexp_replace(split_part(ltrim(coalesce(p,''''),''/''),''?'',1),\n   ''^(https?://[^/]+/storage/v1/object/(sign|public|authenticated)/)?raw-private/'','''')\n$$;\nCREATE FUNCTION public.customer_media_paths(p text[]) RETURNS text[]\nLANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path='''' AS $$\n SELECT coalesce(array_agg(public.customer_media_path(x)),ARRAY[]::text[]) FROM unnest(p) x\n$$;\n\n-- Every branch below has a matching index generated with this core. No owner\n-- filter: a reference belonging to ANY owner protects shared bytes.\nCREATE FUNCTION public.customer_media_referenced(p text,a uuid DEFAULT NULL) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path='''' AS $$\n SELECT EXISTS(SELECT 1 FROM public.creations c WHERE public.customer_media_path(c.customize_snapshot->>''storagePath'')=p)\n OR EXISTS(SELECT 1 FROM public.jobs j WHERE public.customer_media_path(j.input_snapshot->>''face_source_path'')=p)\n OR EXISTS(SELECT 1 FROM public.jobs j WHERE a IS NOT NULL AND j.input_snapshot#>>''{creation_version_fork,face_asset_id}''=a::text)\n OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.output_assets @> jsonb_build_object(''pages'',jsonb_build_array(jsonb_build_object(''storage_path'',p))))\n OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.output_assets @> jsonb_build_object(''pages'',jsonb_build_array(jsonb_build_object(''storage_path_full'',p))))\n OR EXISTS(SELECT 1 FROM public.jobs j WHERE public.customer_media_path(j.output_assets->>''pdf_path'')=p)\n OR EXISTS(SELECT 1 FROM public.preview_share_links s WHERE s.cover_bucket=''raw-private'' AND public.customer_media_path(s.cover_storage_path)=p)\n OR EXISTS(SELECT 1 FROM public.customers c WHERE public.customer_media_path(c.avatar_storage_path)=p)\n OR EXISTS(SELECT 1 FROM public.templates t WHERE public.customer_media_path(t.cover_image_path)=p)\n OR EXISTS(SELECT 1 FROM public.templates t WHERE public.customer_media_path(t.normalized_cover_image_path)=p)\n OR EXISTS(SELECT 1 FROM public.templates t WHERE public.customer_media_path(t.default_config_path)=p)\n OR EXISTS(SELECT 1 FROM public.templates t WHERE public.customer_media_paths(t.showcase_image_paths) @> ARRAY[p])\n OR EXISTS(SELECT 1 FROM public.blog_posts b WHERE public.customer_media_paths(b.image_storage_paths) @> ARRAY[p])\n OR EXISTS(SELECT 1 FROM public.homepage_banner_slots b WHERE public.customer_media_path(b.desktop_asset_path)=p)\n OR EXISTS(SELECT 1 FROM public.homepage_banner_slots b WHERE public.customer_media_path(b.mobile_asset_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_job_pages f WHERE public.customer_media_path(f.ai_output_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_job_pages f WHERE public.customer_media_path(f.manual_output_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_job_pages f WHERE public.customer_media_path(f.approved_output_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_job_pages f WHERE public.customer_media_path(f.print_output_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_jobs f WHERE public.customer_media_path(f.pdf_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_jobs f WHERE public.customer_media_path(f.print_package_path)=p)\n OR EXISTS(SELECT 1 FROM public.final_print_artifacts f WHERE f.storage_bucket=''raw-private'' AND public.customer_media_path(f.storage_path)=p)\n$$;\n\nCREATE FUNCTION public.enqueue_customer_media_removal(a uuid,t text,p text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE q uuid;\nBEGIN\n IF a IS NULL OR t NOT IN (''face_image'',''preview_output'') OR p IS NULL OR p='''' OR p<>public.customer_media_path(p)\n   OR p~''(^|/)\\.\\.(/|$)'' OR p LIKE ''%://%'' OR p LIKE ''app-templates/%'' OR p LIKE ''story-config-private/%'' THEN\n   RAISE EXCEPTION ''customer_removal_invalid_file'' USING ERRCODE=''23514'';\n END IF;\n IF public.customer_media_referenced(p,a) THEN RETURN NULL; END IF;\n IF EXISTS(SELECT 1 FROM public.user_asset_cleanup_outbox WHERE bucket_name=''raw-private'' AND storage_path=p AND cleanup_status=''processing'') THEN\n   RAISE EXCEPTION ''customer_removal_cleanup_in_progress'' USING ERRCODE=''PT409'';\n END IF;\n INSERT INTO public.user_asset_cleanup_outbox(asset_id,asset_type,bucket_name,storage_path,reason,cleanup_status,next_attempt_at,updated_at)\n VALUES(a,t,''raw-private'',p,''owner_delete'',''pending'',clock_timestamp(),clock_timestamp())\n ON CONFLICT(bucket_name,storage_path) DO UPDATE SET\n   next_attempt_at=greatest(public.user_asset_cleanup_outbox.next_attempt_at,excluded.next_attempt_at),updated_at=excluded.updated_at\n WHERE public.user_asset_cleanup_outbox.cleanup_status=''pending'' RETURNING cleanup_id INTO q;\n RETURN q;\nEND $$;\n\n-- The caller holds the asset lock; references are checked again AFTER any wait.\nCREATE FUNCTION public.enqueue_unused_customer_face(a uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE f public.user_assets%rowtype; q uuid;\nBEGIN\n SELECT * INTO f FROM public.user_assets WHERE asset_id=a FOR UPDATE;\n IF NOT FOUND OR f.asset_type::text<>''face_image'' THEN RETURN NULL; END IF;\n IF public.customer_media_referenced(public.customer_media_path(f.storage_path),a) THEN RETURN NULL; END IF;\n q:=public.enqueue_customer_media_removal(a,''face_image'',public.customer_media_path(f.storage_path));\n IF q IS NOT NULL THEN DELETE FROM public.user_assets WHERE asset_id=a; END IF;\n RETURN q;\nEND $$;\n\nCREATE FUNCTION public.prune_owned_unbound_faces(p_owner_type text,p_owner_id uuid,p_keep integer DEFAULT 8) RETURNS integer\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE f record; n integer:=0;\nBEGIN\n IF p_owner_type NOT IN (''customer'',''anon'') OR p_owner_type IS NULL OR p_owner_id IS NULL OR p_keep<>8 THEN\n   RAISE EXCEPTION ''face_prune_input_invalid'' USING ERRCODE=''22023''; END IF;\n FOR f IN SELECT asset_id FROM public.user_assets WHERE asset_type::text=''face_image'' AND owner_type::text=p_owner_type\n   AND ((p_owner_type=''customer'' AND customer_id=p_owner_id) OR (p_owner_type=''anon'' AND anon_session_id=p_owner_id))\n   ORDER BY created_at DESC,asset_id DESC OFFSET p_keep\n LOOP\n   IF public.enqueue_unused_customer_face(f.asset_id) IS NOT NULL THEN n:=n+1; END IF;\n END LOOP;\n RETURN n;\nEND $$;\n\n-- Match cleanup''s asset-row lock at BOTH initial Creation and Job admission.\n-- No mutation on unchanged source paths; existing authorization remains in its\n-- existing writers. This guard adds liveness fencing, not an access grant.\nCREATE FUNCTION public.guard_customer_face_reference() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE p text; f uuid;\nBEGIN\n IF TG_TABLE_NAME=''creations'' THEN\n   p:=public.customer_media_path(NEW.customize_snapshot->>''storagePath'');\n   IF TG_OP=''UPDATE'' AND public.customer_media_path(OLD.customize_snapshot->>''storagePath'')=p THEN RETURN NEW; END IF;\n ELSE\n   IF NEW.job_type::text<>''preview'' THEN RETURN NEW; END IF;\n   p:=public.customer_media_path(NEW.input_snapshot->>''face_source_path'');\n   IF TG_OP=''UPDATE'' AND public.customer_media_path(OLD.input_snapshot->>''face_source_path'')=p THEN RETURN NEW; END IF;\n END IF;\n IF p='''' THEN RETURN NEW; END IF;\n SELECT asset_id INTO f FROM public.user_assets WHERE asset_type::text=''face_image''\n   AND public.customer_media_path(storage_path)=p ORDER BY asset_id LIMIT 1 FOR KEY SHARE;\n IF NOT FOUND OR EXISTS(SELECT 1 FROM public.user_asset_cleanup_outbox WHERE bucket_name=''raw-private'' AND storage_path=p AND cleanup_status=''processing'') THEN\n   RAISE EXCEPTION ''face_source_unavailable'' USING ERRCODE=''PT409''; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER creations_customer_face_reference BEFORE INSERT OR UPDATE OF customize_snapshot ON public.creations\n FOR EACH ROW EXECUTE FUNCTION public.guard_customer_face_reference();\nCREATE TRIGGER jobs_customer_face_reference BEFORE INSERT OR UPDATE OF input_snapshot ON public.jobs\n FOR EACH ROW EXECUTE FUNCTION public.guard_customer_face_reference();\n\nCREATE FUNCTION public.remove_owned_preview_creation(p_creation_id uuid,p_owner_type text,p_owner_id uuid) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE c public.creations%rowtype; root uuid; members integer; archive_mode boolean;\n jids uuid[]; files jsonb; share_files jsonb; source_faces uuid[]; face uuid; file record; n integer:=0; shares integer:=0; affected integer;\nBEGIN\n IF current_setting(''transaction_isolation'')<>''read committed'' THEN RAISE EXCEPTION ''customer_removal_isolation_invalid'' USING ERRCODE=''23514''; END IF;\n IF p_owner_type IS NULL OR p_owner_type NOT IN (''customer'',''anon'') OR p_owner_id IS NULL OR p_creation_id IS NULL THEN\n   RAISE EXCEPTION ''customer_removal_owner_invalid'' USING ERRCODE=''22023''; END IF;\n SELECT * INTO c FROM public.creations WHERE creation_id=p_creation_id AND owner_type::text=p_owner_type\n   AND ((p_owner_type=''customer'' AND customer_id=p_owner_id) OR (p_owner_type=''anon'' AND anon_session_id=p_owner_id));\n IF NOT FOUND THEN RAISE EXCEPTION ''customer_removal_not_found'' USING ERRCODE=''P0002''; END IF;\n SELECT root_creation_id INTO root FROM public.read_preview_version_group(p_creation_id,p_owner_type,p_owner_id) LIMIT 1;\n PERFORM pg_advisory_xact_lock(hashtextextended(''preview-root:''||root::text,0));\n SELECT * INTO c FROM public.creations WHERE creation_id=p_creation_id AND owner_type::text=p_owner_type\n   AND ((p_owner_type=''customer'' AND customer_id=p_owner_id) OR (p_owner_type=''anon'' AND anon_session_id=p_owner_id)) FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''customer_removal_not_found'' USING ERRCODE=''P0002''; END IF;\n SELECT count(*) INTO members FROM public.read_preview_version_group(p_creation_id,p_owner_type,p_owner_id);\n PERFORM 1 FROM public.jobs WHERE creation_id=p_creation_id ORDER BY job_id FOR UPDATE;\n IF EXISTS(SELECT 1 FROM public.jobs WHERE creation_id=p_creation_id AND status::text IN (''queued'',''running'',''cancel_requested'')) THEN\n   RAISE EXCEPTION ''customer_removal_active_work'' USING ERRCODE=''PT409''; END IF;\n PERFORM 1 FROM public.cart_items WHERE creation_id=p_creation_id ORDER BY cart_item_id FOR UPDATE;\n archive_mode:=members>1 OR EXISTS(SELECT 1 FROM public.jobs WHERE creation_id=p_creation_id\n   AND input_snapshot#>>''{creation_version_fork,kind}''=''change_photo'')\n   OR EXISTS(SELECT 1 FROM public.cart_items WHERE creation_id=p_creation_id\n     AND (status::text=''ordered'' OR payment_id IS NOT NULL OR order_id IS NOT NULL))\n   OR EXISTS(SELECT 1 FROM public.final_jobs WHERE creation_id=p_creation_id);\n SELECT coalesce(array_agg(job_id),ARRAY[]::uuid[]) INTO jids FROM public.jobs WHERE creation_id=p_creation_id;\n IF EXISTS(SELECT 1 FROM public.preview_share_links WHERE preview_job_id=ANY(jids) AND creation_id<>p_creation_id) THEN\n   RAISE EXCEPTION ''customer_removal_share_identity_drift'' USING ERRCODE=''23514''; END IF;\n SELECT jsonb_agg(jsonb_build_object(''id'',preview_job_id,''path'',cover_storage_path,''bucket'',cover_bucket)) INTO share_files\n   FROM public.preview_share_links WHERE creation_id=p_creation_id;\n -- BOTH modes revoke all of this Creation''s sharing in this same transaction.\n DELETE FROM public.preview_share_links WHERE creation_id=p_creation_id OR preview_job_id=ANY(jids);\n GET DIAGNOSTICS shares=ROW_COUNT;\n IF archive_mode THEN\n   UPDATE public.creations SET is_archived=true,deleted_at=coalesce(deleted_at,clock_timestamp()),updated_at=clock_timestamp() WHERE creation_id=p_creation_id;\n   RETURN jsonb_build_object(''ok'',true,''mode'',''soft'',''shares_revoked'',shares,''queued_files'',0);\n END IF;\n IF EXISTS(SELECT 1 FROM public.jobs WHERE creation_id=p_creation_id AND coalesce(output_assets->>''bucket'',''raw-private'')<>''raw-private'') THEN\n   RAISE EXCEPTION ''customer_removal_unexpected_bucket'' USING ERRCODE=''23514''; END IF;\n SELECT jsonb_agg(jsonb_build_object(''id'',j.job_id,''path'',p.path)) INTO files FROM public.jobs j\n CROSS JOIN LATERAL (\n   SELECT x->>''storage_path'' path FROM jsonb_array_elements(coalesce(j.output_assets->''pages'',''[]'')) x\n   UNION SELECT x->>''storage_path_full'' FROM jsonb_array_elements(coalesce(j.output_assets->''pages'',''[]'')) x\n   UNION SELECT j.output_assets->>''pdf_path''\n ) p WHERE j.creation_id=p_creation_id AND nullif(p.path,'''') IS NOT NULL;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(share_files,''[]'')) x WHERE x->>''bucket''<>''raw-private'') THEN\n   RAISE EXCEPTION ''customer_removal_unexpected_share_bucket'' USING ERRCODE=''23514''; END IF;\n files:=coalesce(files,''[]'')||coalesce(share_files,''[]'');\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(files,''[]'')) x\n   WHERE x->>''path'' !~ (''^jobs/[0-9]{4}/[0-9]{2}/[0-9]{2}/''||(x->>''id'')||''/attempt_[0-9]{3}/output/page_[0-9]{2}(_full)?[.](png|jpg|webp)$'')) THEN\n   RAISE EXCEPTION ''customer_removal_output_path_invalid'' USING ERRCODE=''23514''; END IF;\n SELECT coalesce(array_agg(a.asset_id ORDER BY a.asset_id),ARRAY[]::uuid[]) INTO source_faces FROM public.user_assets a\n WHERE a.asset_type::text=''face_image'' AND a.owner_type::text=p_owner_type\n   AND ((p_owner_type=''customer'' AND a.customer_id=p_owner_id) OR (p_owner_type=''anon'' AND a.anon_session_id=p_owner_id))\n   AND (public.customer_media_path(a.storage_path)=public.customer_media_path(c.customize_snapshot->>''storagePath'')\n     OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.job_id=ANY(jids)\n       AND (public.customer_media_path(j.input_snapshot->>''face_source_path'')=public.customer_media_path(a.storage_path)\n         OR j.input_snapshot#>>''{creation_version_fork,face_asset_id}''=a.asset_id::text)));\n PERFORM 1 FROM public.user_assets WHERE asset_id=ANY(source_faces) ORDER BY asset_id FOR UPDATE;\n DELETE FROM public.cart_items WHERE creation_id=p_creation_id;\n DELETE FROM public.creation_dedications WHERE creation_id=p_creation_id;\n DELETE FROM public.jobs WHERE job_id=ANY(jids);\n DELETE FROM public.creations WHERE creation_id=p_creation_id;\n GET DIAGNOSTICS affected=ROW_COUNT;\n IF affected<>1 THEN RAISE EXCEPTION ''customer_removal_row_count'' USING ERRCODE=''23514''; END IF;\n FOR file IN SELECT DISTINCT (x->>''id'')::uuid id,x->>''path'' path FROM jsonb_array_elements(coalesce(files,''[]'')) x LOOP\n   IF public.enqueue_customer_media_removal(file.id,''preview_output'',file.path) IS NOT NULL THEN n:=n+1; END IF;\n END LOOP;\n FOREACH face IN ARRAY source_faces LOOP\n   IF public.enqueue_unused_customer_face(face) IS NOT NULL THEN n:=n+1; END IF;\n END LOOP;\n RETURN jsonb_build_object(''ok'',true,''mode'',''hard'',''shares_revoked'',shares,''queued_files'',n);\nEND $$;\n","index_sql":"CREATE INDEX web28_creations_face_path_idx ON public.creations USING btree (public.customer_media_path(customize_snapshot->>''storagePath''));\nCREATE INDEX web28_jobs_face_path_idx ON public.jobs USING btree (public.customer_media_path(input_snapshot->>''face_source_path''));\nCREATE INDEX web28_jobs_face_id_idx ON public.jobs USING btree ((input_snapshot#>>''{creation_version_fork,face_asset_id}''));\nCREATE INDEX web28_jobs_fork_parent_idx ON public.jobs USING btree ((input_snapshot#>>''{creation_version_fork,source_creation_id}''),(input_snapshot#>>''{creation_version_fork,source_preview_job_id}''));\nCREATE INDEX web28_jobs_output_pages_idx ON public.jobs USING gin (output_assets jsonb_path_ops);\nCREATE INDEX web28_jobs_pdf_idx ON public.jobs USING btree (public.customer_media_path(output_assets->>''pdf_path''));\nCREATE INDEX web28_preview_share_links_path_idx ON public.preview_share_links USING btree (cover_bucket,public.customer_media_path(cover_storage_path));\nCREATE INDEX web28_user_assets_path_idx ON public.user_assets USING btree (public.customer_media_path(storage_path));\nCREATE INDEX web28_customers_avatar_idx ON public.customers USING btree (public.customer_media_path(avatar_storage_path));\nCREATE INDEX web28_templates_cover_idx ON public.templates USING btree (public.customer_media_path(cover_image_path));\nCREATE INDEX web28_templates_normalized_idx ON public.templates USING btree (public.customer_media_path(normalized_cover_image_path));\nCREATE INDEX web28_templates_config_idx ON public.templates USING btree (public.customer_media_path(default_config_path));\nCREATE INDEX web28_templates_showcase_idx ON public.templates USING gin (public.customer_media_paths(showcase_image_paths));\nCREATE INDEX web28_blog_posts_images_idx ON public.blog_posts USING gin (public.customer_media_paths(image_storage_paths));\nCREATE INDEX web28_homepage_banner_slots_desktop_idx ON public.homepage_banner_slots USING btree (public.customer_media_path(desktop_asset_path));\nCREATE INDEX web28_homepage_banner_slots_mobile_idx ON public.homepage_banner_slots USING btree (public.customer_media_path(mobile_asset_path));\nCREATE INDEX web28_final_job_pages_ai_output_idx ON public.final_job_pages USING btree (public.customer_media_path(ai_output_path));\nCREATE INDEX web28_final_job_pages_manual_output_idx ON public.final_job_pages USING btree (public.customer_media_path(manual_output_path));\nCREATE INDEX web28_final_job_pages_approved_output_idx ON public.final_job_pages USING btree (public.customer_media_path(approved_output_path));\nCREATE INDEX web28_final_job_pages_print_output_idx ON public.final_job_pages USING btree (public.customer_media_path(print_output_path));\nCREATE INDEX web28_final_jobs_pdf_idx ON public.final_jobs USING btree (public.customer_media_path(pdf_path));\nCREATE INDEX web28_final_jobs_package_idx ON public.final_jobs USING btree (public.customer_media_path(print_package_path));\nCREATE INDEX web28_final_print_artifacts_path_idx ON public.final_print_artifacts USING btree (storage_bucket,public.customer_media_path(storage_path));","indexes":[{"name":"web28_creations_face_path_idx","table":"creations","method":"btree","expression":"public.customer_media_path(customize_snapshot->>''storagePath'')","definition":"CREATE INDEX web28_creations_face_path_idx ON public.creations USING btree (customer_media_path((customize_snapshot ->> ''storagePath''::text)))"},{"name":"web28_jobs_face_path_idx","table":"jobs","method":"btree","expression":"public.customer_media_path(input_snapshot->>''face_source_path'')","definition":"CREATE INDEX web28_jobs_face_path_idx ON public.jobs USING btree (customer_media_path((input_snapshot ->> ''face_source_path''::text)))"},{"name":"web28_jobs_face_id_idx","table":"jobs","method":"btree","expression":"(input_snapshot#>>''{creation_version_fork,face_asset_id}'')","definition":"CREATE INDEX web28_jobs_face_id_idx ON public.jobs USING btree (((input_snapshot #>> ''{creation_version_fork,face_asset_id}''::text[])))"},{"name":"web28_jobs_fork_parent_idx","table":"jobs","method":"btree","expression":"(input_snapshot#>>''{creation_version_fork,source_creation_id}''),(input_snapshot#>>''{creation_version_fork,source_preview_job_id}'')","definition":"CREATE INDEX web28_jobs_fork_parent_idx ON public.jobs USING btree (((input_snapshot #>> ''{creation_version_fork,source_creation_id}''::text[])), ((input_snapshot #>> ''{creation_version_fork,source_preview_job_id}''::text[])))"},{"name":"web28_jobs_output_pages_idx","table":"jobs","method":"gin","expression":"output_assets jsonb_path_ops","definition":"CREATE INDEX web28_jobs_output_pages_idx ON public.jobs USING gin (output_assets jsonb_path_ops)"},{"name":"web28_jobs_pdf_idx","table":"jobs","method":"btree","expression":"public.customer_media_path(output_assets->>''pdf_path'')","definition":"CREATE INDEX web28_jobs_pdf_idx ON public.jobs USING btree (customer_media_path((output_assets ->> ''pdf_path''::text)))"},{"name":"web28_preview_share_links_path_idx","table":"preview_share_links","method":"btree","expression":"cover_bucket,public.customer_media_path(cover_storage_path)","definition":"CREATE INDEX web28_preview_share_links_path_idx ON public.preview_share_links USING btree (cover_bucket, customer_media_path(cover_storage_path))"},{"name":"web28_user_assets_path_idx","table":"user_assets","method":"btree","expression":"public.customer_media_path(storage_path)","definition":"CREATE INDEX web28_user_assets_path_idx ON public.user_assets USING btree (customer_media_path(storage_path))"},{"name":"web28_customers_avatar_idx","table":"customers","method":"btree","expression":"public.customer_media_path(avatar_storage_path)","definition":"CREATE INDEX web28_customers_avatar_idx ON public.customers USING btree (customer_media_path(avatar_storage_path))"},{"name":"web28_templates_cover_idx","table":"templates","method":"btree","expression":"public.customer_media_path(cover_image_path)","definition":"CREATE INDEX web28_templates_cover_idx ON public.templates USING btree (customer_media_path(cover_image_path))"},{"name":"web28_templates_normalized_idx","table":"templates","method":"btree","expression":"public.customer_media_path(normalized_cover_image_path)","definition":"CREATE INDEX web28_templates_normalized_idx ON public.templates USING btree (customer_media_path(normalized_cover_image_path))"},{"name":"web28_templates_config_idx","table":"templates","method":"btree","expression":"public.customer_media_path(default_config_path)","definition":"CREATE INDEX web28_templates_config_idx ON public.templates USING btree (customer_media_path(default_config_path))"},{"name":"web28_templates_showcase_idx","table":"templates","method":"gin","expression":"public.customer_media_paths(showcase_image_paths)","definition":"CREATE INDEX web28_templates_showcase_idx ON public.templates USING gin (customer_media_paths(showcase_image_paths))"},{"name":"web28_blog_posts_images_idx","table":"blog_posts","method":"gin","expression":"public.customer_media_paths(image_storage_paths)","definition":"CREATE INDEX web28_blog_posts_images_idx ON public.blog_posts USING gin (customer_media_paths(image_storage_paths))"},{"name":"web28_homepage_banner_slots_desktop_idx","table":"homepage_banner_slots","method":"btree","expression":"public.customer_media_path(desktop_asset_path)","definition":"CREATE INDEX web28_homepage_banner_slots_desktop_idx ON public.homepage_banner_slots USING btree (customer_media_path(desktop_asset_path))"},{"name":"web28_homepage_banner_slots_mobile_idx","table":"homepage_banner_slots","method":"btree","expression":"public.customer_media_path(mobile_asset_path)","definition":"CREATE INDEX web28_homepage_banner_slots_mobile_idx ON public.homepage_banner_slots USING btree (customer_media_path(mobile_asset_path))"},{"name":"web28_final_job_pages_ai_output_idx","table":"final_job_pages","method":"btree","expression":"public.customer_media_path(ai_output_path)","definition":"CREATE INDEX web28_final_job_pages_ai_output_idx ON public.final_job_pages USING btree (customer_media_path(ai_output_path))"},{"name":"web28_final_job_pages_manual_output_idx","table":"final_job_pages","method":"btree","expression":"public.customer_media_path(manual_output_path)","definition":"CREATE INDEX web28_final_job_pages_manual_output_idx ON public.final_job_pages USING btree (customer_media_path(manual_output_path))"},{"name":"web28_final_job_pages_approved_output_idx","table":"final_job_pages","method":"btree","expression":"public.customer_media_path(approved_output_path)","definition":"CREATE INDEX web28_final_job_pages_approved_output_idx ON public.final_job_pages USING btree (customer_media_path(approved_output_path))"},{"name":"web28_final_job_pages_print_output_idx","table":"final_job_pages","method":"btree","expression":"public.customer_media_path(print_output_path)","definition":"CREATE INDEX web28_final_job_pages_print_output_idx ON public.final_job_pages USING btree (customer_media_path(print_output_path))"},{"name":"web28_final_jobs_pdf_idx","table":"final_jobs","method":"btree","expression":"public.customer_media_path(pdf_path)","definition":"CREATE INDEX web28_final_jobs_pdf_idx ON public.final_jobs USING btree (customer_media_path(pdf_path))"},{"name":"web28_final_jobs_package_idx","table":"final_jobs","method":"btree","expression":"public.customer_media_path(print_package_path)","definition":"CREATE INDEX web28_final_jobs_package_idx ON public.final_jobs USING btree (customer_media_path(print_package_path))"},{"name":"web28_final_print_artifacts_path_idx","table":"final_print_artifacts","method":"btree","expression":"storage_bucket,public.customer_media_path(storage_path)","definition":"CREATE INDEX web28_final_print_artifacts_path_idx ON public.final_print_artifacts USING btree (storage_bucket, customer_media_path(storage_path))"}],"functions":[{"name":"customer_media_path","body_md5":"73f9d11537c21c6dbc63ed56dcb9bac1","security_definer":false,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"customer_media_paths","body_md5":"ccc099a96beeabf7a8f623a4e6c436d2","security_definer":false,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"customer_media_referenced","body_md5":"3c7e8d14b3c42541f92f3f16653a5579","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"enqueue_customer_media_removal","body_md5":"ba7895f7a80ddb9dc909a512b358760b","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"enqueue_unused_customer_face","body_md5":"1542774e7608ce4d0156aef4bce9891b","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"prune_owned_unbound_faces","body_md5":"ccf6946ee90fb82c7f9fb56929f838ba","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres,service_role=X/postgres}"},{"name":"guard_customer_face_reference","body_md5":"378cf935f709ce106343447b65c3e038","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres}"},{"name":"remove_owned_preview_creation","body_md5":"aa5fe098f3e9317676de34e11e8fb386","security_definer":true,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","raw_acl":"{postgres=X/postgres,service_role=X/postgres}"}]}'::jsonb; r jsonb; f record; d text; signature text; contract_before jsonb;contract_after jsonb;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'web28_operator_mismatch'; END IF;
 PERFORM set_config('lock_timeout','5s',true);
 IF to_regprocedure('public.customer_media_path(text)') IS NOT NULL THEN RAISE EXCEPTION 'web28_already_installed'; END IF;
 LOCK TABLE public.creations,public.jobs,public.user_assets,public.user_asset_cleanup_outbox,public.preview_share_links IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN SELECT value FROM jsonb_array_elements(payload->'before') LOOP
 SELECT p.oid,p.prosrc,p.proacl::text acl,p.prosecdef,pg_get_userbyid(p.proowner) owner,md5(p.proconfig::text) config_md5 INTO f
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))=r->>'identity';
 IF f.oid IS NULL OR md5(f.prosrc) IS DISTINCT FROM r->>'raw_body_md5' OR f.acl IS DISTINCT FROM r->>'raw_acl'
 OR f.owner IS DISTINCT FROM r->>'owner' OR f.prosecdef IS DISTINCT FROM (r->>'security_definer')::boolean
 OR f.config_md5 IS DISTINCT FROM r->>'config_md5' THEN RAISE EXCEPTION 'web28_source_drift:%',r->>'identity'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_array(c.oid,c.relowner,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity) ORDER BY c.oid) INTO contract_before
 FROM pg_class c WHERE c.oid IN ('public.creations'::regclass,'public.jobs'::regclass,'public.user_assets'::regclass,'public.user_asset_cleanup_outbox'::regclass,'public.preview_share_links'::regclass);
 EXECUTE payload->>'core';
 EXECUTE payload->>'index_sql';
 FOR r IN SELECT value FROM jsonb_array_elements(payload->'patches') LOOP
  SELECT p.oid,p.prosrc,pg_get_functiondef(p.oid) definition INTO f FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))=r->>'identity';
  EXECUTE replace(f.definition,f.prosrc,r->>'body');
 END LOOP;
 FOR f IN SELECT p.oid,p.proname,p.oid::regprocedure::text signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='public' AND p.proname IN (SELECT x->>'name' FROM jsonb_array_elements(payload->'functions') x) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);
  IF f.proname IN ('remove_owned_preview_creation','prune_owned_unbound_faces') THEN
   EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature); END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(payload->'patches') LOOP
  SELECT p.prosrc,p.proacl::text acl,pg_get_userbyid(p.proowner) owner INTO f FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))=r->>'identity';
  IF md5(f.prosrc)<>r->>'after_md5' OR f.acl IS DISTINCT FROM r#>>'{before,raw_acl}' OR f.owner IS DISTINCT FROM r#>>'{before,owner}' THEN
   RAISE EXCEPTION 'web28_after_drift'; END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(payload->'functions') LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'
    AND p.proname=r->>'name' AND md5(p.prosrc)=r->>'body_md5' AND p.proacl::text=r->>'raw_acl'
    AND p.prosecdef=(r->>'security_definer')::boolean AND md5(p.proconfig::text)=r->>'config_md5' AND pg_get_userbyid(p.proowner)='postgres') THEN
    RAISE EXCEPTION 'web28_new_function_custody_drift'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_array(c.oid,c.relowner,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity) ORDER BY c.oid) INTO contract_after
 FROM pg_class c WHERE c.oid IN ('public.creations'::regclass,'public.jobs'::regclass,'public.user_assets'::regclass,'public.user_asset_cleanup_outbox'::regclass,'public.preview_share_links'::regclass);
 IF contract_after IS DISTINCT FROM contract_before THEN RAISE EXCEPTION 'web28_table_custody_drift'; END IF;
END $web28$;
